import {
    Component,
    OnInit,
    OnDestroy,
    ViewChild,
    ElementRef,
    HostListener,
    inject,
} from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { StockService } from 'src/app/stock/stock.service';
import { Subscription } from 'rxjs';
import { tap } from 'rxjs/operators';
import { Products } from 'src/app/core/interfaces/stock.interface';
import { SellService } from '../sell.service';
import { Message } from 'primeng/api';
import { ConfirmationService } from 'primeng/api';
import { Table } from 'primeng/table';
import { LocalStorageService } from 'src/app/_services/local-storage.service';
import { AutoCompleteCompleteEvent } from 'primeng/autocomplete';
import {
    Customers,
    InvoiceItems,
    InvoiceTotals,
    LatestPurchaseItem,
} from 'src/app/core/interfaces/customer.interface';
import { PrintService } from 'src/app/print.service';
import { AuxiliaryService } from 'src/app/accounting/auxiliary.service';
import { AuxiliaryAccount } from 'src/app/core/interfaces/accounts.interface';
import { LinksService } from 'src/app/components/links-component/links.service';

@Component({
    selector: 'sell-form',
    templateUrl: './sell-form.component.html',
    styleUrls: ['./sell-form.component.scss'],
})
export class SellFormComponent implements OnInit, OnDestroy {
    // barcode input reference
    @ViewChild('barcodeInput', { read: ElementRef }) barcodeInput: ElementRef;

    @ViewChild('invoiceTable') invoiceTable: Table;

    // focus on right click
    @HostListener('document:contextmenu')
    preventContextMenu() {
        //
        return false;
    }

    // focus barcode input on keydown
    @HostListener('document:keydown', ['$event'])
    onKeyDown(ev: KeyboardEvent) {
        if (!this.dialogVisible) {
            if (
                ev.key == 'Enter' &&
                this.order_items.length > 0 &&
                !this.barcode
            ) {
                setTimeout(() => {
                    // this.submitDebt();
                }, 100);
            }
        }
    }

    constructor(
        private stockService: StockService,
        public sellService: SellService,
        private confirmationService: ConfirmationService,
        private localStorageService: LocalStorageService,
        private auxiliaryService: AuxiliaryService,
        private printService: PrintService,
    ) {}

    readonly linksService = inject(LinksService);

    links = this.linksService.links;
    loadingLinks = this.linksService.loadingLinks;

    message: Message[];

    subscriptions = new Subscription();

    items: Products[] = [];

    customers: AuxiliaryAccount[];

    searchedItems: any | undefined;

    order_items: InvoiceItems[];
    invoiceTotal: InvoiceTotals;
    barcode: any | undefined;
    barcodeResponse: Products;
    factor: number;

    dialogVisible: boolean = false;
    exchangeRate;

    stateOptions;
    stateValue: string;

    all_expanded = false;

    selectedCustomerLatestItems: LatestPurchaseItem[];

    form_error = false;
    invoiceToPrint;

    // get view height for scrollable invoice table
    vh = this.localStorageService.getSellPageViewHeight();

    ngOnInit(): void {
        this.message = [
            { severity: 'info', detail: 'No items in this category yet!' },
        ];

        this.subscriptions.add(
            this.auxiliaryService.customers.subscribe((res) => {
                this.customers = res;
            }),
        );

        this.subscriptions.add(
            this.stockService.items.subscribe((res) => {
                this.items = res;
            }),
        );

        this.subscriptions.add(
            this.sellService.invoice_items
                .pipe(
                    tap((re) => {
                        this.sellService.calculateTotal();
                        if (this.barcodeInput) {
                        }
                    }),
                )
                .subscribe((res) => {
                    this.order_items = res;
                }),
        );

        this.subscriptions.add(
            this.sellService.invoiceTotal.subscribe((res) => {
                this.invoiceTotal = res;
            }),
        );
        this.subscriptions.add(
            this.sellService.barcodeResponse.subscribe((res) => {
                this.barcodeResponse = res;
                if (res) {
                    this.addToInvoice();
                    this.sellService.barcodeResponse.next(0);
                }
            }),
        );
        this.subscriptions.add(
            this.sellService.factor.subscribe((res) => {
                this.factor = res;
            }),
        );
        this.subscriptions.add(
            this.stockService.exchangeRate.subscribe((res) => {
                this.exchangeRate = res;
            }),
        );
        this.subscriptions.add(
            this.sellService.stateOptions.subscribe((res) => {
                this.stateOptions = res;
            }),
        );
        this.subscriptions.add(
            this.sellService.stateValue.subscribe((res) => {
                this.stateValue = res;
            }),
        );

        this.subscriptions.add(
            this.customer_id.statusChanges.subscribe((res) => {
                // this.sellService.customer_id.next(this.customer_id.value);
                if (this.customer_id.value)
                    this.sellService.getCustomerLatestPurchase(
                        this.customer_id.value,
                    );
                else {
                    this.selectedCustomerLatestItems = [];
                    this.all_expanded = true;
                    this.toggleTableRows();
                }
            }),
        );
        this.subscriptions.add(
            this.sellService.selectedCustomerLatestItems.subscribe((res) => {
                this.selectedCustomerLatestItems = res;
            }),
        );
        this.subscriptions.add(
            this.sellService.customer_id.subscribe((res) => {
                this.customer_id.patchValue(res);
            }),
        );

        this.subscriptions.add(
            this.sellService.reset_form_validations$.subscribe((res) => {
                if (res) {
                    this.resetFormValidation();
                    this.sellService.reset_form_validations$.next(false);
                }
            }),
        );
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    // toggle table rows
    toggleTableRows() {
        this.all_expanded = !this.all_expanded;
        if (this.all_expanded) {
            // If all_expanded is true, set every row to expanded.
            this.order_items.forEach((item) => {
                if (
                    this.getCustomerItemHistory(item) &&
                    this.getCustomerItemHistory(item).length > 0
                )
                    this.invoiceTable.expandedRowKeys[item.product_id] = true;
            });
        } else {
            // If all_expanded is false, collapse every row.
            if (this.invoiceTable) {
                setTimeout(() => {
                    this.invoiceTable.expandedRowKeys = {};
                });
            }
        }
    }

    // change customer
    customerChange(event) {
        this.sellService.customer_id.next(this.customer_id.value);
    }

    // search items
    searchItem(event: AutoCompleteCompleteEvent) {
        let filtered: any = [];
        let query = event.query;
        for (let i = 0; i < this.items.length; i++) {
            let item = this.items[i];
            if (
                item.product_name.toLowerCase().indexOf(query.toLowerCase()) >
                -1
            ) {
                // == 0 for exact search
                filtered.push(item);
            }
        }
        this.searchedItems = filtered;
    }

    submitInvoiceInput(event: KeyboardEvent) {
        if (event.key === 'Enter') {
            if (this.barcode) {
                if (typeof this.barcode == 'string') {
                    this.submitBarcode(this.barcode);
                } else {
                    this.sellService.barcodeResponse.next(this.barcode);
                }
                this.barcode = null;
            }
        }
    }
    // submit barcode
    submitBarcode(barcode) {
        if (barcode) {
            let index = -1;
            let allowedSymbols = ['*', '+'];
            for (let i = 0; i < allowedSymbols.length; i++) {
                if (barcode.indexOf(allowedSymbols[i]) !== -1) {
                    index = barcode.indexOf(allowedSymbols[i]);
                    break;
                }
            }

            let factor = barcode.substring(0, index) || 1;
            let actualBarcode = parseInt(
                barcode.substring(index + 1, barcode.length),
            );
            if (index != -1 && index != 0) {
                this.sellService.factor.next(parseInt(factor));
                this.sellService.submitBarcode(actualBarcode);
            } else {
                this.sellService.submitBarcode(barcode);
            }
        }
    }

    // open sell dialog
    openProductsDialog() {
        this.dialogVisible = true;
    }

    // close sell dialog
    closeProductsDialog() {
        this.dialogVisible = false;
    }

    // get selected products from dialog event
    assignSelectedProducts(products) {
        this.dialogVisible = false;
        products.forEach((element) => {
            this.sellService.barcodeResponse.next(element);
        });
    }

    // debt form
    debtForm = new FormGroup({
        customer_id: new FormControl(
            this.sellService.customer_id.value,
            Validators.required,
        ),
        invoice_number: new FormControl(null),
        total_cost: new FormControl(null),
        total_amount: new FormControl(null),
        sub_total: new FormControl(null),
        exchange_rate: new FormControl(null),
        has_discount: new FormControl(null),
        discount_value: new FormControl(null),
        discount_percent: new FormControl(null),
        discount2_value: new FormControl(null),
        discount2_percent: new FormControl(null),
        include_vat: new FormControl(null),
        vat_value: new FormControl(null),
        vat_value_lbp: new FormControl(null),
        order_datetime: new FormControl(this.sellService.invoice_date),
        order_notes: new FormControl(null),
        include_delivery: new FormControl(null),
        delivery_charge: new FormControl(null),
        link_id: new FormControl(null),
    });
    get customer_id() {
        return this.debtForm.get('customer_id');
    }

    // add barcode response to invoice
    addToInvoice() {
        let item = this.barcodeResponse;
        let itemToAdd = {
            product_id: item.product_id,
            sku: item.sku,
            barcode: item.barcode,
            product_name: item.product_name,
            unit_cost: item.average_cost_usd,
            unit_price:
                this.sellService.priceOption == 'original'
                    ? item.unit_price_usd
                    : item.ttc_price,
            quantity: this.factor,
        };

        // let found = false;
        // this.order_items.forEach((element, index) => {
        //     if (
        //         element.product_id == itemToAdd.product_id &&
        //         element.product_id != 0
        //     ) {
        //         this.order_items[index].quantity += this.factor;
        //         found = true;
        //     }
        // });
        // console.log(found);

        // if (!found) {
        this.order_items.push(itemToAdd);
        if (this.invoiceTable) {
            setTimeout(() => {
                this.invoiceTable.scrollTo({
                    top: this.invoiceTable.wrapperViewChild.nativeElement
                        .scrollHeight,
                });
            }, 10);
        }
        // }
        this.sellService.invoice_items.next(this.order_items);
        this.sellService.factor.next(1);
    }

    // subtract qty
    removeRow(index) {
        this.order_items.splice(index, 1);
        this.sellService.invoice_items.next(this.order_items);
    }

    //set price using text input
    setPrice(item: InvoiceItems) {
        if (!item.unit_price) {
            this.form_error = false;
        } else {
            this.form_error = false;
        }
        this.sellService.calculateTotal('edit');
    }
    //set QTY using text input
    setQty(item: InvoiceItems) {
        if (!item.quantity) {
            this.form_error = true;
        } else {
            this.form_error = false;
        }
        this.sellService.calculateTotal('edit');
    }

    // submit debt form
    submitDebt() {
        this.sellService.submitted = true;
        if (
            this.debtForm.valid &&
            this.form_error === false &&
            this.sellService.invoice_number_error === false
        ) {
            // prettier-ignore
            if (
                this.sellService.is_lira_payment &&
                (this.sellService.payment_amount &&
                    !this.sellService.payment_amount_lbp) ||
                (!this.sellService.payment_amount &&
                    this.sellService.payment_amount_lbp)
            ) {
                return;
            }

            this.confirmationService.confirm({
                key: 'checkout',
                message: `Are you sure you want to continue"?`,
                header: 'Warning',
                icon: 'pi pi-exclamation-triangle',
                closeOnEscape: false,
            });
        }
    }

    // clear invoice
    clearInvoice() {
        this.confirmationService.confirm({
            key: 'clearInvoice',
            message: `Are you sure that you want to clear invoice"?`,
            header: 'Warning',
            icon: 'pi pi-exclamation-triangle',
            acceptButtonStyleClass: 'p-button-danger',
            rejectButtonStyleClass: 'p-button-secondary',
            defaultFocus: 'reject',
            accept: () => {
                // this.sellService.clearInvoiceAction();
                this.sellService.invoice_items.next([]);
                this.resetForm();
            },
            reject: () => {},
        });
    }

    // reset debt form
    resetForm() {
        this.sellService.submitted = false;
        this.debtForm.reset({
            customer_id: null,
            order_notes: null,
        });
        this.sellService.customer_id.next(null);
    }

    resetFormValidation() {
        this.debtForm.markAsPristine();
        this.debtForm.markAsUntouched();
        this.debtForm.updateValueAndValidity();
    }

    calculate_vat() {
        this.sellService.include_vat = !this.sellService.include_vat;
        this.sellService.calculate_additional_totals(this.invoiceTotal);
    }

    calculateDelivery() {
        this.sellService.include_delivery = !this.sellService.include_delivery;
        this.sellService.calculate_additional_totals(this.invoiceTotal);
    }

    // select input on focus
    select(event) {
        event.select();
    }

    calculate_discount(event, type = 'amount') {
        // this.sellService.calculateTotal()
        if (type === 'percent_total') {
            if (this.sellService.discount_percent_on_total > 100) {
                this.sellService.discount_percent_on_total = 100;
            }
        } else if (type === 'percent') {
            if (this.sellService.discount_percent > 100) {
                this.sellService.discount_percent = 100;
            }
        }
        this.sellService.calculate_additional_totals(this.invoiceTotal);
    }

    getCustomerItemHistory(item: InvoiceItems) {
        return this.selectedCustomerLatestItems.filter(
            (x) => x.product_id == item.product_id,
        );
    }

    togglePaymentType(event) {
        this.sellService.is_lira_payment = event;
        if (!this.sellService.is_lira_payment) {
            this.sellService.payment_amount_lbp = null;
        }
    }

    getTypedInvoiceItems(item: any) {
        return item as InvoiceItems;
    }

    printInvoice() {
        this.printService.print(this.invoiceToPrint, 'sale');
    }

    confirmCheckoutDialog(print_flag = false) {
        this.debtForm.patchValue({
            total_cost: this.invoiceTotal.total_dollar_cost,
            total_amount: this.invoiceTotal.total_dollar,
            sub_total: this.invoiceTotal.total_dollar_price,
            exchange_rate: this.exchangeRate.rate_value,
            discount_value: this.invoiceTotal.discount_amount_dollar,
            discount_percent: this.sellService.discount_value
                ? null
                : this.sellService.discount_percent,
            discount2_value:
                this.sellService.discount_percent_on_total > 0
                    ? this.invoiceTotal.secondary_discount_amount_dollar
                    : null,
            discount2_percent:
                this.sellService.discount_percent_on_total > 0
                    ? this.sellService.discount_percent_on_total
                    : null,

            has_discount: this.invoiceTotal.discount_amount_dollar > 0,
            include_vat: this.sellService.include_vat,
            vat_value: this.invoiceTotal.vat_dollar,
            vat_value_lbp: this.invoiceTotal.vat_lira,
            order_datetime: this.sellService.invoice_date,
            include_delivery: this.sellService.include_delivery,
            delivery_charge: this.sellService.delivery_charge,
        });
        const payment = {
            payment_amount: this.sellService.payment_amount,
            payment_amount_value: this.sellService.is_lira_payment
                ? this.sellService.payment_amount_lbp
                : this.sellService.payment_amount,
            currency: this.sellService.is_lira_payment ? 'lira' : 'dollar',
            payment_notes: 'Sell Invoice Payment',
            customer_id: this.customer_id.value,
            exchange_rate: this.exchangeRate.rate_value,
        };
        this.sellService.checkout(
            this.debtForm.value,
            this.order_items,
            payment,
            this.customer_id.value,
            print_flag,
        );

        this.resetForm();

        this.confirmationService.close();
    }
    rejectCheckoutDialog() {
        this.confirmationService.close();
    }
    saveAndPrintInvoice() {
        this.confirmCheckoutDialog(true);
    }

    // formatedInvoiceNumber() {
    //     return `INV${this.sellService.invoice_number
    //         .toString()
    //         .padStart(5, '0')}`;
    // }
    setInvoiceNumber($event) {
        // this.sellService.invoice_number = $event;
        if ($event.length < 8) return;
        if ($event.length > 0) {
            this.sellService.checkInvoiceNumber($event);
        }
    }
}
