import { Component, ViewChild } from '@angular/core';
import { SellService } from '../sell.service';
import { Subscription } from 'rxjs';
import { PendingInvoices } from 'src/app/core/interfaces/customer.interface';
import { ConfirmationService } from 'primeng/api';
import { Scroller } from 'primeng/scroller';

@Component({
    selector: 'app-sell-toolbar',
    templateUrl: './sell-toolbar.component.html',
    styleUrl: './sell-toolbar.component.scss',
})
export class SellToolbarComponent {
    items!: PendingInvoices[];
    subscriptions = new Subscription();
    active_index = -1;
    active_id = 0;

    @ViewChild('sc') sc!: Scroller;

    constructor(
        public sellService: SellService,
        private confirmationService: ConfirmationService
    ) {}
    ngOnInit() {
        this.subscriptions.add(
            this.sellService.pending_invoices$.subscribe((items) => {
                this.items = items;

                if (this.active_id === 0 && items.length > 0) {
                    this.active_id = items[items.length - 1].order_id;
                }
            })
        );

        this.subscriptions.add(
            this.sellService.active_invoice.subscribe((index) => {
                this.active_index = index;
                if (this.sc) {
                    this.sc.scrollToIndex(index, 'smooth');
                }

                if (index !== -1 && this.items.length > 0) {
                    this.active_id = this.items[index].order_id;
                }
            })
        );
    }

    ngOnDestroy() {
        this.subscriptions.unsubscribe();
    }

    openNewInvoice(id: number = 0) {
        // this.sellService.storeCurrentInvoice(true);
    }

    deleteInvoice(index: number) {
        let pending_invoices = this.sellService.pending_invoices$.value;
        const invoice_id = pending_invoices[index].order_id;
        this.confirmationService.confirm({
            key: 'clearInvoice',
            message: `Are you sure that you want to DELETE invoice #${invoice_id}?`,
            header: 'Warning',
            icon: 'pi pi-exclamation-triangle',
            acceptButtonStyleClass: 'p-button-danger',
            rejectButtonStyleClass: 'p-button-secondary',
            defaultFocus: 'reject',
            accept: () => {
                // this.sellService.deletePendingInvoice(invoice_id);
            },
            reject: () => {
                // this.focusInput();
            },
        });
    }

    changeActiveInvoice(index: number) {
        if (this.active_index === index) return;
        this.sellService.submitted = false;
    }
}
